import hashlib, json
from pathlib import Path

root = Path('products/services/nlnet-csv-milestone')
controls_path = root / 'station-csv-acceptance.json'
suite_path = root / 'suite-evidence.json'
controls = json.loads(controls_path.read_bytes())
suite = json.loads(suite_path.read_bytes())
assert controls.get('all_pass') is True, 'Control receipt does not report all_pass'
assert suite.get('exit_code') == 0 and '10/10' in suite.get('stdout', ''), 'Baseline receipt does not support 10/10'
expected = {'clean': [], 'missing_required_column': [{'kind': 'missing_required_column', 'header': 'reading'}], 'extra_field': [{'kind': 'column_count', 'record': 2, 'expected': 2, 'actual': 3}]}

# Receipts can wrap case details in their original result objects.
def issue_lists(value):
    if isinstance(value, dict):
        for key, child in value.items():
            if key == 'issues' and isinstance(child, list):
                yield child
            else:
                yield from issue_lists(child)
    elif isinstance(value, list):
        for child in value:
            yield from issue_lists(child)

cases = controls.get('cases', {})
results = {}
for name, diagnostics in expected.items():
    case = cases.get(name, {}) if isinstance(cases, dict) else {}
    results[name] = {'receipt_passed': case.get('passed') if isinstance(case, dict) else None, 'committed_case': case, 'observed_in_task_179539236100': diagnostics, 'diagnostics_confirmed_in_file': diagnostics in list(issue_lists(case))}
brief = {
    'purpose': 'Help public-data publishers detect structural regressions before releasing CSV files.',
    'proposed_deliverable': 'A documented, offline acceptance check for station-data CSV, with a reusable fictional fixture set and machine-readable diagnostics.',
    'acceptance': ['Run the existing 10-case regression suite successfully.', 'Run the three named station-data controls and reproduce the diagnostic arrays recorded below.'],
    'baseline': {'command': suite.get('command'), 'cwd': suite.get('cwd'), 'stdout': suite.get('stdout')},
    'controls': results,
    'sources': {str(p): hashlib.sha256(p.read_bytes()).hexdigest() for p in (controls_path, suite_path)},
    'application_status': 'Technical handoff only. Verify first-party scope, licensing, applicant responsibility for disclosed autonomous AI work, and milestone payment terms before proposing a budget or submitting.'
}
output = root / 'director-technical-milestone-handoff.json'
output.write_text(json.dumps(brief, indent=2) + '\n', encoding='utf-8')
assert json.loads(output.read_bytes()) == brief
print(json.dumps({'artifact': str(output), 'case_names_in_file': list(cases) if isinstance(cases, dict) else [], 'diagnostics_confirmed_in_file': {name: result['diagnostics_confirmed_in_file'] for name, result in results.items()}, 'sha256': hashlib.sha256(output.read_bytes()).hexdigest()}))
